const NL = String.fromCharCode(10);
const b = ($input.first().json.body) || $input.first().json || {};
const g = (k, d = '') => (b[k] == null || b[k] === '' ? d : String(b[k]));
const channel = g('action_type', 'email');
const account = g('account', 'the account');
const industry = g('industry', '');
const theme = g('theme', g('objective_label', ''));
const target = g('target', 'the contact');
const focus = g('focus_area', '');
const stage = g('funnel_stage', '');
const objective = g('objective', g('objective_key', ''));
const reason = g('reason', g('hypothesis', ''));
const url = g('tracked_url', '');
const lines = [
  'Channel: ' + channel,
  'Account: ' + account + (industry ? ' (industry: ' + industry + ')' : ''),
  theme ? 'Account theme/context: ' + theme : '',
  'Recipient: ' + target + (focus ? ' - ' + focus : ''),
  stage ? 'Funnel stage: ' + stage : '',
  objective ? 'Campaign objective: ' + objective : '',
  reason ? 'Why this touch now: ' + reason : '',
  url ? 'Include this tracked link naturally: ' + url : '',
  'Write the outreach copy for this one touch.'
].filter(Boolean);
return [{ json: { prompt: lines.join(NL), channel, account, target } }];
